python3 -I - <<'EOF'
path='/var/tmp/loop-bench/runs/4c53af45b520/ci-6/coverage/lcov.info'
import re
cur=None; fnnames={}; fnhit={}
for line in open(path):
    line=line.strip()
    if line.startswith('SF:'): cur=line[3:]
    elif line.startswith('FN:'):
        n,name=line[3:].split(',',1); fnnames.setdefault(cur,{})[n]=name
    elif line.startswith('FNDA:'):
        n,rest=line[5:].split(',',1); fnhit.setdefault(cur,{})[rest]=int(n)
    elif line.startswith('end_of_record'):
        d=fnnames.get(cur,{}); h=fnhit.get(cur,{})
        miss=[(name,c) for n,name in d.items() for c in [h.get(name,0)] if c==0]
        if miss:
            tot=len(d); hit=len(d)-len(miss)
            print(f"{cur}: {hit}/{tot} covered")
            for name,c in miss: print(f"   UNCOVERED fn {name}")
        cur=None; fnnames.pop(cur,None) if cur in fnnames else None
